import { test, expect } from '@playwright/test';

test.describe('Error Clearing on Invalid Input Correction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should clear error message when user corrects invalid input', async ({ page }) => {
    // Setup: Fill form with invalid data
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('john.doe@example.com');

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Name is required');
    await expect(errorMessage).toBeVisible();

    // Verify form is not submitted
    const formStatus = page.getByRole('status');
    await expect(formStatus).toContainText('Form is invalid');

    // User corrects invalid input
    await nameInput.fill('Jane Doe');

    // Verify error message is cleared
    await expect(errorMessage).not.toBeVisible();

    // Verify form is now valid
    await expect(formStatus).toContainText('Form is valid');

    // Verify form is submitted
    await expect(submitButton).toBeEnabled();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should not clear error message when user submits with invalid data', async ({ page }) => {
    // Setup: Fill form with invalid data
    const nameInput = page.getByLabel('Name');
    await nameInput.fill('');

    const emailInput = page.getByLabel('Email');
    await emailInput.fill('invalid-email');

    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify error message appears
    const errorMessage = page.getByText('Name is required');
    await expect(errorMessage).toBeVisible();

    // Verify form is not submitted
    const formStatus = page.getByRole('status');
    await expect(formStatus).toContainText('Form is invalid');

    // User attempts to correct invalid input
    await nameInput.fill('Jane Doe');

    // Verify error message persists
    await expect(errorMessage).toBeVisible();

    // Verify form is still not valid
    await expect(formStatus).toContainText('Form is invalid');

    // Verify submit button is still disabled
    await expect(submitButton).not.toBeEnabled();

    // Verify success message does not appear
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();
  });
});
